class NumberConverter:
    # Define symbolic constants to avoid magic numbers
    BASE_2 = 2
    BASE_8 = 8
    BASE_16 = 16
    STRIP_PREFIX_LENGTH = 2

    @staticmethod
    def decimal_to_binary(decimal_num):
        return bin(decimal_num)[NumberConverter.STRIP_PREFIX_LENGTH:]

    @staticmethod
    def binary_to_decimal(binary_num):
        return int(binary_num, NumberConverter.BASE_2)

    @staticmethod
    def decimal_to_octal(decimal_num):
        return oct(decimal_num)[NumberConverter.STRIP_PREFIX_LENGTH:]

    @staticmethod
    def octal_to_decimal(octal_num):
        return int(octal_num, NumberConverter.BASE_8)

    @staticmethod
    def decimal_to_hex(decimal_num):
        return hex(decimal_num)[NumberConverter.STRIP_PREFIX_LENGTH:]

    @staticmethod
    def hex_to_decimal(hex_num):
        return int(hex_num, NumberConverter.BASE_16)
